#!/usr/bin/env node
import { homedir } from 'node:os';
import { join } from 'node:path';
import { belongsToWorkspace, makeTrailRecord, recordTrailState, recordWorkspaceTrail, trailStateDirectory } from './trail-state.ts';

try {
  const args = process.argv.slice(2);
  const url = args.shift(), status = args.shift();
  const observedAt = args[0] && !args[0].startsWith('--') ? args.shift() : undefined;
  const owner = {};
  while (args.length) {
    const flag = args.shift(), value = args.shift();
    if (!['--workspace', '--pane'].includes(flag) || !value || value.startsWith('--') || flag in owner) throw new Error('Expected --workspace <owner-id> --pane <owner-pane-id>');
    owner[flag] = value;
  }
  const explicit = Object.keys(owner).length > 0;
  const workspaceId = explicit ? owner['--workspace'] : process.env.HERDR_ENV === '1' ? process.env.HERDR_WORKSPACE_ID : undefined;
  const paneId = explicit ? owner['--pane'] : process.env.HERDR_ENV === '1' ? process.env.HERDR_PANE_ID : undefined;
  const scoped = explicit || process.env.HERDR_ENV === '1';
  if (scoped && !belongsToWorkspace(workspaceId, paneId)) throw new Error('Expected matching owning workspace/pane IDs; relayers must supply both explicitly');
  const record = makeTrailRecord(url, status, observedAt);
  const directory = process.env.TRAIL_LEDGER_DIR || join(homedir(), '.local/state/herdr/orchestrations');
  if (scoped) await recordWorkspaceTrail(directory, url, workspaceId, paneId);
  await recordTrailState(trailStateDirectory(directory), url, status, record.observed_at);
} catch (error) {
  process.stderr.write(`${error.message}\n`);
  process.exitCode = 1;
}

