// Exercise every simple-git call shape node-llama-cpp 3.22.1 uses, against simple-git v4.
import { simpleGit } from "/Users/alex/.herdr/worktrees/entire-brain/alex-fix-vulns/scripts/bench/node_modules/simple-git/dist/index.mjs";
import fs from "node:fs";
import path from "node:path";

const root = process.argv[2];
fs.rmSync(root, { recursive: true, force: true });
fs.mkdirSync(root, { recursive: true });
const src = path.join(root, "src");
fs.mkdirSync(src);
const env = { GIT_CONFIG_NOSYSTEM: "1", HOME: root };

const g = simpleGit(src).env({ ...process.env, ...env });
await g.init();
await g.addConfig("user.name", "t");
await g.addConfig("user.email", "t@t");
await g.addConfig("commit.gpgsign", "false");
fs.writeFileSync(path.join(src, "a.txt"), "hello\n");
await g.add(["a.txt"]);
await g.commit("init");
await g.tag(["b1000"]);
const log = await g.log(["-1"]);
console.log("log.latest.hash", log.latest.hash.slice(0, 8));
const tree = await g.raw(["commit-tree", "HEAD^{tree}", "-m", "squash"]);
await g.reset(["--hard", tree.trim()]);
console.log("tags", (await g.tags()).all);
console.log("branch.current", (await g.branch()).current);
console.log("revparse", (await g.revparse(["HEAD"])).slice(0, 8));
const bundle = path.join(root, "x.bundle");
await g.raw(["bundle", "create", bundle, "HEAD"]);

let progressSeen = false;
const pg = simpleGit({ progress() { progressSeen = true; } });
const fromBundle = path.join(root, "from-bundle");
await pg.clone(bundle, fromBundle, { "--quiet": null });
await simpleGit(fromBundle).removeRemote("origin");
console.log("bundle clone ok, remotes", (await simpleGit(fromBundle).getRemotes()).length);

const fromUrl = path.join(root, "from-url");
await pg.clone("file://" + src, fromUrl, { "--depth": 1, "--branch": "b1000", "--quiet": null });
const c = simpleGit(fromUrl);
console.log("listRemote get-url", (await c.listRemote(["--get-url", "origin"])).trim().startsWith("file://"));
await c.fetch(["--unshallow"]);
await c.addRemote("o2", "file://" + src);
await c.tag(["--delete", "b1000"]).catch(() => {});
await c.branch(["--delete", "nonexistent"]).catch(() => {});

const patch = path.join(root, "p.diff");
fs.writeFileSync(patch, "--- a/a.txt\n+++ b/a.txt\n@@ -1 +1 @@\n-hello\n+world\n");
await simpleGit({ baseDir: fromUrl }).applyPatch(patch, { "--ignore-whitespace": null });
console.log("patched", fs.readFileSync(path.join(fromUrl, "a.txt"), "utf8").trim());
console.log("progress option accepted", typeof progressSeen === "boolean");

